/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: load, loadV2, freeze, entry, asStoredV2, keyPaths
 *   Constants: actor, v1Fixtures, publicationFixtures, environment, previous
 * Tests
 *   - every v1 fixture maps deterministically onto the Draft v2 view without changing the stored document
 *   - the Draft v2 view is idempotent: storing it as Draft v2 reads back the same view
 *   - a v1 artistName becomes one primary entry whose legacy key is shared by the draft, baseline, snapshot and artist decision
 *   - an empty artistName has no entry, and its pending suggestion becomes a pending artists suggestion
 *   - every value of a v1 project is the administrator's own, over exactly the Draft v2 value paths
 *   - a v1 artist decision binds to the legacy entry and its name; other decisions carry no entry
 *   - publication snapshots map into the view while the stored v1 snapshot stays unchanged
 *   - the v1 draft projection is a deep copy of every v1 draft and keeps stored track order
 *   - draft and publication format versions accept only absent, null or a positive safe integer; formats 1 and 2 are writable for imports and reviews
 *   - an approval is format 1 only with a v1 snapshot, so a newer snapshot without a recorded format fails closed
 *   - a Draft v2 project projects onto only v1 DTO fields and offers no analysis, upload or publication
 *   - unknown publication and analysis states degrade to needs attention without inventing recovery or identities
 *   - an unrecognized draft format still projects one valid v1 draft per manifest slot
 *   - assets outside the v1 slots, states, lifecycles or identities are hidden from a v1 client
 *   - catalog review sources keep known fields and a captured Disc Number, applied evidence keeps disc fields and is never dropped
 *   - the Draft v2 editor view keeps only readable entries, label and values, one track per slot in stored order, and never throws
 *   - the Draft v2 suggestion view maps legacy Artist names, keeps readable album Artist suggestions whole and drops any other
 *   - the Draft v2 suggestion view hides an Artist suggestion that proposes a placeholder such as Various Artists
 *   - the Draft v2 suggestion view shows readable label and Disc Number suggestions, hides malformed ones and never projects lookup context
 *   - the Draft v2 decision view keeps one readable decision per entry, label, Album and track, each naming its entry or none and its bound name
 *   - the editor asset view allowlists version-2 tag evidence and reads evidence stored before it as version 1; the v1 DTO keeps five tag fields
 *   - the published view lists every credited Artist and the label of a format-3 approval, maps a legacy Artist to one entry, and is null when malformed
 *   - a stored cover selection is an explicit choice, while a project with none shows the automatic shared embedded image to v1 clients too
 * @end-catalog */

/**
 * Forward-compatible reads of stored import projects. The frozen v1 fixtures must map deterministically and
 * idempotently onto the Draft v2 view later stages adopt, and a document a newer release stored (the synthetic
 * fixture in test/fixtures/adminImportCompat) must project back onto exactly the v1 admin contract, read-only.
 */
import assert from 'node:assert/strict';
import { after, before, test } from 'node:test';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import { uuid } from '../../src/administration/import/adminImportContract';
import { importPublicationSupported, importPublicationVersion } from '../../src/administration/import/adminImportMediaTypes';
import { adminImportDetail, adminImportDto, importDigest, type AdminImportDocument } from '../../src/administration/import/adminImportService';
import {
    catalogReviewAppliedView, catalogReviewSourceDisc, catalogReviewSourceView, importDecisionsV2View, importDraftV2FromV1, importDraftV2View, importDraftVersion, importDraftWritable, importProjectV2View,
    importPublishedV2View, importSuggestionsV2View, legacyArtistEntryKey, legacyAssetsView, legacyAssetVisible, legacyDecisionsView, legacyDraftView, legacyPublicationView, legacySuggestionsView, writableDraftFilter, type ImportProjectV2View
} from '../../src/administration/import/adminImportDraftCompat';
import { importTagsV2View } from '../../src/administration/import/adminImportTags';
import type { CatalogReviewApplied, CatalogReviewSource } from '../../src/administration/catalog/adminCatalogReviewContract';
import { loadImportFixture } from '../support/adminImportFixtures';

const actor = '0000000000000000000000a1';
const v1Fixtures = ['v1-draft.json', 'v1-analysis-pending-artist-name.json', 'v1-assets-reviewed.json', 'v1-decisions-album-reuse.json', 'v1-publication-preparing.json',
    'v1-publication-needs-attention.json', 'v1-publication-cancelled-cleanup-pending.json', 'v1-publication-complete.json', 'v1-publication-complete-album-reuse.json'];
const publicationFixtures = v1Fixtures.filter(name => name.startsWith('v1-publication-'));
const load = (name: string) => loadImportFixture('adminImport', name);
const loadV2 = () => loadImportFixture('adminImportCompat', 'v2-draft-project.json');
const environment = { FINITUDE_ADMIN_IMPORTS_ENABLED: 'true', FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY: 'true', ADMIN_IMPORT_S3_BUCKET_NAME: 'synthetic-private-imports', S3_BUCKET_NAME: 'synthetic-catalog' };
const previous = Object.fromEntries(Object.keys(environment).map(key => [key, process.env[key]]));
before(() => { Object.assign(process.env, environment); });
after(() => { for (const [key, value] of Object.entries(previous)) { if (value === undefined) delete process.env[key]; else process.env[key] = value; } });

/** Freezes plain objects and arrays in place; ObjectId and Date instances stay usable. */
const freeze = <T>(value: T): T => {
    if (value && typeof value === 'object' && (Array.isArray(value) || Object.getPrototypeOf(value) === Object.prototype)) { for (const child of Object.values(value)) freeze(child); Object.freeze(value); }
    return value;
};
const entry = (key: string, name: string) => ({ key, name, role: 'primary', joinPhrase: null, musicBrainzId: null });
/** Stores a view back as a Draft v2 document, the shape a later release would persist. */
const asStoredV2 = (doc: AdminImportDocument, view: ImportProjectV2View) => ({
    ...doc, draftVersion: 2, draft: view.draft, draftOrigins: view.draftOrigins, analysis: { ...doc.analysis, baseline: view.baseline }, decisions: view.decisions, suggestions: view.suggestions,
    media: doc.media && { ...doc.media, ...(doc.media.publication ? { publication: { ...doc.media.publication, snapshot: view.snapshot } } : {}) }
}) as unknown as AdminImportDocument;
/** Every key path of a JSON value, with array positions collapsed. */
const keyPaths = (value: unknown, prefix = '', paths = new Set<string>()): Set<string> => {
    if (Array.isArray(value)) for (const child of value) keyPaths(child, `${prefix}[]`, paths);
    else if (value && typeof value === 'object') for (const [key, child] of Object.entries(value)) { paths.add(`${prefix}.${key}`); keyPaths(child, `${prefix}.${key}`, paths); }
    return paths;
};

test('every v1 fixture maps deterministically onto the Draft v2 view without changing the stored document', () => {
    for (const name of v1Fixtures) {
        const doc = freeze(load(name)), stored = JSON.stringify(doc);
        const first = importProjectV2View(doc), second = importProjectV2View(doc);
        assert.ok(first, name); assert.deepEqual(first, second, name);
        adminImportDto(doc, actor, true); legacyDraftView(doc.draft, doc.manifest);
        assert.equal(JSON.stringify(doc), stored, name);
    }
});

test('the Draft v2 view is idempotent: storing it as Draft v2 reads back the same view', () => {
    for (const name of v1Fixtures) {
        const doc = load(name), view = importProjectV2View(doc)!;
        assert.deepEqual(importProjectV2View(asStoredV2(doc, view)), view, name);
    }
});

test('a v1 artistName becomes one primary entry whose legacy key is shared by the draft, baseline, snapshot and artist decision', () => {
    const doc = load('v1-draft.json'), view = importProjectV2View(doc)!, key = legacyArtistEntryKey(doc._id.toHexString());
    assert.equal(uuid(key), true); assert.equal(legacyArtistEntryKey(doc._id.toHexString()), key); assert.notEqual(legacyArtistEntryKey('0'.repeat(24)), key);
    assert.deepEqual(view.draft, {
        album: { title: 'Synthetic Album', artists: [entry(key, 'Lorem Ensemble & Ipsum Quartet')], label: null, releaseDate: { year: 2025, month: 6, day: null }, visibility: 'hidden' },
        tracks: doc.draft.tracks.map(({ slotId, title, trackNumber }) => ({ slotId, title, discNumber: null, trackNumber }))
    });
    assert.deepEqual([view.baseline, view.snapshot, view.decisions, view.suggestions], [null, null, [], []]);
    for (const name of v1Fixtures) {
        const doc = load(name), view = importProjectV2View(doc)!, key = legacyArtistEntryKey(doc._id.toHexString());
        const drafts = [view.draft, view.baseline, view.snapshot].filter(value => value !== null);
        const keys = [...drafts.flatMap(draft => draft!.album.artists.map(value => value.key)), ...view.decisions.filter(decision => decision.scope === 'artist').map(decision => decision.entryKey)];
        // An artist decision binds the legacy entry only while the draft has one, that is, a non-empty artistName.
        assert.ok(keys.every(value => value === (doc.draft.album.artistName.trim() ? key : null)), name);
        for (const draft of drafts) { assert.equal(draft!.album.label, null, name); assert.ok(draft!.tracks.every(track => track.discNumber === null), name); }
    }
});

test('an empty artistName has no entry, and its pending suggestion becomes a pending artists suggestion', () => {
    const doc = load('v1-analysis-pending-artist-name.json'), view = importProjectV2View(doc)!, key = legacyArtistEntryKey(doc._id.toHexString());
    assert.deepEqual([view.draft.album.artists, view.baseline!.album.artists], [[], []]);
    const index = doc.suggestions.findIndex(suggestion => suggestion.field === 'artistName' && suggestion.decision === 'pending');
    assert.ok(index >= 0);
    assert.deepEqual(view.suggestions[index], { ...doc.suggestions[index], field: 'artists', baseline: [], value: [entry(key, 'Synthetic Artist')] });
    assert.equal(view.suggestions[index].decision, 'pending');
    doc.suggestions.forEach((suggestion, position) => { if (suggestion.field !== 'artistName') assert.deepEqual(view.suggestions[position], suggestion); });
});

test('every value of a v1 project is the administrator\'s own, over exactly the Draft v2 value paths', () => {
    for (const name of v1Fixtures) {
        const doc = load(name), { draftOrigins } = importProjectV2View(doc)!;
        const expected = [...['title', 'artists', 'label', 'releaseDate', 'visibility'].map(field => `album:${field}`),
            ...doc.manifest.files.flatMap(file => ['title', 'discNumber', 'trackNumber'].map(field => `tracks:${file.slotId}:${field}`))];
        assert.deepEqual(Object.keys(draftOrigins).sort(), expected.sort(), name);
        assert.ok(Object.values(draftOrigins).every(origin => origin === 'administrator'), name);
    }
    // A Draft v2 document keeps the origins it stored.
    const v2 = loadV2(); assert.deepEqual(importProjectV2View(v2)!.draftOrigins, v2.draftOrigins);
});

test('a v1 artist decision binds to the legacy entry and its name; other decisions carry no entry', () => {
    const doc = load('v1-decisions-album-reuse.json'), view = importProjectV2View(doc)!, key = legacyArtistEntryKey(doc._id.toHexString());
    assert.ok(doc.draft.album.artistName.trim());
    assert.deepEqual(view.decisions, doc.decisions.map(decision => ({ ...decision, entryKey: decision.scope === 'artist' ? key : null, boundName: decision.scope === 'artist' ? doc.draft.album.artistName : null })));
    // Without a name the view has no legacy entry, so the artist decision binds none rather than a missing key.
    for (const artistName of ['', '   ']) {
        const unnamed = load('v1-decisions-album-reuse.json'); unnamed.draft.album.artistName = artistName;
        const { draft, decisions } = importProjectV2View(unnamed)!;
        assert.deepEqual(draft.album.artists, [], JSON.stringify(artistName));
        assert.deepEqual(decisions, unnamed.decisions.map(decision => ({ ...decision, entryKey: null, boundName: null })), JSON.stringify(artistName));
    }
});

test('publication snapshots map into the view while the stored v1 snapshot stays unchanged', () => {
    for (const name of publicationFixtures) {
        const doc = load(name), stored = structuredClone(doc.media!.publication!.snapshot), view = importProjectV2View(doc)!;
        assert.deepEqual(view.snapshot, importDraftV2FromV1(stored, doc._id.toHexString()), name);
        assert.deepEqual(doc.media!.publication!.snapshot, stored, name);
    }
    // A mixed document keeps its Draft v2 value and still converts a frozen v1 snapshot beside it.
    const v2 = loadV2(), frozen = load('v1-publication-preparing.json').media!.publication!;
    const view = importProjectV2View({ ...v2, media: { ...v2.media!, publication: frozen } })!;
    assert.deepEqual(view.draft, v2.draft); assert.notEqual(view.draft, v2.draft);
    assert.deepEqual(view.snapshot!.album.artists.map(value => value.key), [legacyArtistEntryKey(v2._id.toHexString())]);
});

test('the v1 draft projection is a deep copy of every v1 draft and keeps stored track order', () => {
    for (const name of v1Fixtures) {
        const doc = load(name);
        for (const draft of [doc.draft, doc.analysis.baseline, doc.media?.publication?.snapshot]) {
            if (!draft) continue;
            const view = legacyDraftView(draft, doc.manifest);
            assert.deepEqual(view, draft, name); assert.notEqual(view, draft, name); assert.notEqual(view.album, draft.album, name); assert.notEqual(view.tracks[0], draft.tracks[0], name);
        }
    }
    const doc = load('v1-assets-reviewed.json'), [first, second, third] = doc.draft.tracks;
    assert.deepEqual(legacyDraftView({ ...doc.draft, tracks: [third, first, first] }, doc.manifest).tracks, [third, first, { slotId: second.slotId, title: '', trackNumber: null }]);
    // Values beyond the v1 bounds become empty rather than truncated; later fields are dropped.
    assert.deepEqual(legacyDraftView({ album: { title: 'x'.repeat(301), artistName: 'y'.repeat(201), releaseDate: { year: 2025, month: 2, day: 30 }, visibility: 'unlisted' },
        tracks: [{ ...first, title: 'z'.repeat(301), trackNumber: 0, discNumber: 2 }] }, doc.manifest), {
        album: { title: '', artistName: '', releaseDate: null, visibility: 'hidden' },
        tracks: [{ slotId: first.slotId, title: '', trackNumber: null }, { slotId: second.slotId, title: '', trackNumber: null }, { slotId: third.slotId, title: '', trackNumber: null }]
    });
    // Without a v1 artistName, the first primary entry names the Artist, then the first entry.
    const artists = (values: object[]) => legacyDraftView({ album: { title: '', artists: values, releaseDate: null, visibility: 'public' }, tracks: [] }, doc.manifest).album.artistName;
    assert.deepEqual([artists([{ name: 'Guest', role: 'featured' }, { name: 'Primary', role: 'primary' }]), artists([{ name: 'Guest', role: 'featured' }]), artists([])], ['Primary', 'Guest', '']);
});

test('draft and publication format versions accept only absent, null or a positive safe integer; formats 1 and 2 are writable for imports and reviews', () => {
    const cases: [unknown, number | null][] = [[undefined, 1], [null, 1], [1, 1], [2, 2], [3, 3], ['1', null], [0, null], [-1, null], [1.5, null], [Number.NaN, null]];
    const { snapshot } = load('v1-publication-preparing.json').media!.publication!;
    for (const [value, expected] of cases) {
        const doc = value === undefined ? {} : { draftVersion: value }, publication = value === undefined ? { snapshot } : { schemaVersion: value, snapshot };
        assert.equal(importDraftVersion(doc), expected, String(value)); assert.equal(importDraftWritable(doc), expected === 1 || expected === 2, String(value));
        // This release writes Draft v2 catalog reviews too, so format 2 is writable whatever the purpose.
        for (const purpose of ['import', null, 'catalogReview']) assert.equal(importDraftWritable({ ...doc, purpose }), expected === 1 || expected === 2, `${String(value)} ${purpose}`);
        // A v1 snapshot is format 1 only: a format-2 or format-3 approval must freeze a Draft v2 snapshot.
        assert.equal(importPublicationVersion(publication), expected, String(value)); assert.equal(importPublicationSupported(publication), expected === 1, String(value));
        const view = importProjectV2View({ ...load('v1-draft.json'), ...doc } as AdminImportDocument);
        assert.equal(view === null, expected === null || expected > 2, String(value));
    }
    assert.deepEqual(writableDraftFilter, { draftVersion: { $in: [null, 1, 2] } });
});

test('an approval is format 1 only with a v1 snapshot, so a newer snapshot without a recorded format fails closed', () => {
    for (const name of publicationFixtures) assert.equal(importPublicationSupported(load(name).media!.publication!), true, name);
    const { snapshot } = load('v1-publication-preparing.json').media!.publication!, { artistName, ...album } = snapshot.album;
    const v2Album = { ...album, artists: [entry(legacyArtistEntryKey('0'.repeat(24)), artistName)], label: null };
    for (const [label, changed] of [
        ['no snapshot', undefined], ['a scalar snapshot', 'snapshot'], ['no album', { tracks: snapshot.tracks }], ['Draft v2 artist entries', { ...snapshot, album: v2Album }],
        ['entries beside a v1 name', { ...snapshot, album: { ...snapshot.album, artists: [] } }], ['a non-string artistName', { ...snapshot, album: { ...snapshot.album, artistName: null } }],
        ['Disc Numbers', { ...snapshot, tracks: snapshot.tracks.map(track => ({ ...track, discNumber: 1 })) }], ['no track list', { ...snapshot, tracks: {} }], ['a malformed track', { ...snapshot, tracks: [...snapshot.tracks, null] }]
    ] as const) for (const schemaVersion of [undefined, 1]) assert.equal(importPublicationSupported({ schemaVersion, snapshot: changed }), false, `${label} ${schemaVersion}`);
});

test('a Draft v2 project projects onto only v1 DTO fields and offers no analysis, upload or publication', () => {
    const doc = loadV2(), item = adminImportDto(doc, actor, true), [slot1, slot2] = doc.manifest.files.map(file => file.slotId);
    const allowed = new Set(v1Fixtures.flatMap(name => [...keyPaths(adminImportDto(load(name), actor, true))]));
    for (const path of keyPaths(item)) assert.ok(allowed.has(path), path);
    assert.deepEqual(item.manifest, doc.manifest);
    assert.deepEqual(item.draft, { album: { title: 'Synthetic Compat Album', artistName: 'Synthetic Primary', releaseDate: { year: 2026, month: 3, day: null }, visibility: 'public' },
        tracks: [{ slotId: slot1, title: 'Synthetic Opening', trackNumber: 1 }, { slotId: slot2, title: 'Synthetic Reprise', trackNumber: 1 }] });
    assert.deepEqual(item.analysis, { state: 'queued', generation: 1, operationId: doc.analysis.operationId, completedChunks: 1, totalChunks: 2, attemptsUsed: 1, maxAttempts: 22, issue: null });
    assert.deepEqual(item.suggestions.map(({ scope, field, value }) => [scope, field, value]), [['album', 'title', 'Synthetic Compat Album (Deluxe)']]);
    assert.deepEqual(item.decisions.map(({ scope, slotId }) => [scope, slotId]), [['artist', null], ['album', null], ['track', slot1], ['track', slot2]]);
    assert.deepEqual(item.assets.map(asset => [asset.slotId, asset.state]), [[slot1, 'ready'], [`embedded-${slot1}`, 'ready']]);
    assert.deepEqual(item.assets[0].tags, { title: 'Synthetic Opening', album: 'Synthetic Compat Album', artists: ['Synthetic Primary', 'Synthetic Guest'], year: 2026, trackNumber: 1 });
    assert.deepEqual(item.receipts.map(receipt => receipt.kind), ['create', 'edit', 'upload', 'analyze']);
    assert.deepEqual([item.selectedCoverSlotId, item.capabilities, item.publication, item.publicationRecovery, item.published, item.upload],
        [null, { analysis: false, upload: false, publish: false }, 'notStarted', null, null, { ready: 1, total: 2, available: true }]);
    const json = JSON.stringify(item);
    for (const sentinel of ['futureAlbumField', 'musicBrainzId', 'discNumber', 'draftOrigins', 'draftVersion', 'Synthetic Label', 'albumArtist', 'identifiers', 'lookup-', 'futureTopLevel', 'entryKey', 'patch', 'automatic']) assert.equal(json.includes(sentinel), false, sentinel);
    // The stored edit fingerprints the v1 projection a v1 client sent, so its receipt replays.
    const edit = doc.receipts.find(receipt => receipt.kind === 'edit')!;
    assert.equal(edit.hash, importDigest({ kind: 'edit', body: { operationId: edit.operationId, expectedRevision: edit.revision - 1, draft: item.draft } }));
    // Marking a v1 document as a newer format changes nothing a v1 client reads except the capabilities.
    const v1 = load('v1-assets-reviewed.json'), marked = adminImportDto({ ...v1, draftVersion: 2 }, actor, true), plain = adminImportDto(v1, actor, true);
    assert.deepEqual(plain.capabilities, { analysis: true, upload: true, publish: true });
    assert.deepEqual(marked, { ...plain, capabilities: { analysis: false, upload: false, publish: false } });
});

test('unknown publication and analysis states degrade to needs attention without inventing recovery or identities', () => {
    const cancelled = load('v1-publication-cancelled-cleanup-pending.json'), publication = cancelled.media!.publication!;
    const unknown = adminImportDto({ ...cancelled, media: { ...cancelled.media!, publication: { ...publication, state: 'archived' as 'cancelled' } } }, actor, true);
    assert.deepEqual([unknown.publication, unknown.publicationRecovery], ['needsAttention', { operationId: publication.operationId, cleanupPending: false, startedByMe: true }]);
    assert.deepEqual(legacyPublicationView({ ...publication, operationId: 'not-a-uuid' }, actor), { publication: 'needsAttention', publicationRecovery: null, published: null });
    const complete = load('v1-publication-complete.json'), { artistId: _artistId, ...withoutArtist } = complete.media!.publication!;
    const missing = adminImportDto({ ...complete, media: { ...complete.media!, publication: withoutArtist } } as unknown as AdminImportDocument, actor, true);
    assert.deepEqual([missing.publication, missing.published], ['complete', null]);
    const draft = load('v1-draft.json'), analysis = adminImportDto({ ...draft, analysis: { ...draft.analysis, state: 'paused', issue: 'lookupUnavailable' } } as unknown as AdminImportDocument, actor, true).analysis;
    assert.deepEqual([analysis.state, analysis.issue], ['needsAttention', null]);
});

test('an unrecognized draft format still projects one valid v1 draft per manifest slot', () => {
    const doc = { ...load('v1-draft.json'), draftVersion: 3, draft: { album: 'x', tracks: 'y' } } as unknown as AdminImportDocument, item = adminImportDto(doc, actor, true);
    assert.deepEqual(item.draft, { album: { title: '', artistName: '', releaseDate: null, visibility: 'hidden' }, tracks: doc.manifest.files.map(file => ({ slotId: file.slotId, title: '', trackNumber: null })) });
    assert.deepEqual(item.capabilities, { analysis: false, upload: false, publish: false });
    assert.equal(importProjectV2View(doc), null);
});

test('assets outside the v1 slots, states, lifecycles or identities are hidden from a v1 client', () => {
    const doc = load('v1-assets-reviewed.json'), slots = new Set(doc.manifest.files.map(file => file.slotId)), [audio] = doc.media!.assets;
    assert.equal(legacyAssetVisible(audio, slots), true);
    for (const change of [{ slotId: 'lookup-1' }, { slotId: 'embedded-unknown' }, { state: 'staging' }, { recovery: { ...audio.recovery, kind: 'automatic' } }, { sha256: audio.sha256.toUpperCase() }, { byteLength: -1 }, { recovery: { ...audio.recovery, operationId: 'nope' } }]) {
        assert.equal(legacyAssetVisible({ ...audio, ...change } as typeof audio, slots), false, JSON.stringify(change));
    }
    // A lookup cover is shown in every state but removed; a malformed lookup slot never is.
    const lookup = { ...audio, slotId: 'lookup-musicbrainz:0000000b-0000-4000-8000-000000000001', contentType: 'image/jpeg' };
    for (const state of ['pending', 'ready', 'failed', 'unknown', 'deleting', 'cleanupFailed'] as const) assert.equal(legacyAssetVisible({ ...lookup, state }, slots), true, state);
    assert.equal(legacyAssetVisible({ ...lookup, state: 'deleted' }, slots), false);
    for (const slotId of ['lookup-musicbrainz:0000000B-0000-4000-8000-000000000001', 'lookup-musicbrainz:x', 'lookup-itunes:1', 'lookup-', `lookup-musicbrainz:0000000b-0000-4000-8000-000000000001/x`]) {
        assert.equal(legacyAssetVisible({ ...lookup, slotId }, slots), false, slotId);
    }
    // In the projections, a ready lookup cover can be the selected cover; its removed record never shows.
    const projected = { ...doc, media: { ...doc.media!, assets: [...doc.media!.assets, { ...lookup, state: 'ready' as const }, { ...lookup, slotId: 'lookup-musicbrainz:0000000b-0000-4000-8000-000000000002', state: 'deleted' as const }],
        selectedCoverSlotId: lookup.slotId } } as AdminImportDocument;
    const dto = adminImportDto(projected, doc.actorId);
    assert.deepEqual(dto.assets.filter(asset => asset.slotId.startsWith('lookup-')).map(asset => asset.slotId), [lookup.slotId]);
    assert.equal(dto.selectedCoverSlotId, lookup.slotId);
});

test('catalog review sources keep known fields and a captured Disc Number, applied evidence keeps disc fields and is never dropped', () => {
    const slot = '00000009-0000-4000-a000-0000000000d1', slotTwo = '00000009-0000-4000-a000-0000000000d2', revision = `cr_${'a'.repeat(43)}`;
    const v1: CatalogReviewSource = { album: { id: '0000000000000000000000d1', revision, title: 'Synthetic Album', releaseDate: { year: 2020, month: null, day: null }, visibility: 'hidden' },
        tracks: [{ slotId: slot, id: '0000000000000000000000d2', revision, title: 'Synthetic Track', trackNumber: 1, originalFileName: '01 - Synthetic Track.mp3' }, { slotId: slotTwo, id: '0000000000000000000000d3', revision, title: 'Second', trackNumber: null, originalFileName: null }] };
    // A review created before Disc Numbers were captured shows no disc; a captured disc (a number or null) is kept.
    assert.deepEqual(catalogReviewSourceView(v1), v1);
    const captured = { ...v1, tracks: [{ ...v1.tracks[0], discNumber: 2 }, { ...v1.tracks[1], discNumber: null }] };
    assert.deepEqual(catalogReviewSourceView(captured), captured);
    const later = { album: { ...v1.album, discCount: 2 }, tracks: [{ ...v1.tracks[0], discNumber: 2, futureField: true }, { ...v1.tracks[1], originalFileName: 'folder/name.mp3' }] } as unknown as CatalogReviewSource;
    assert.deepEqual(catalogReviewSourceView(later), { ...v1, tracks: [{ ...v1.tracks[0], discNumber: 2 }, { ...v1.tracks[1], originalFileName: null }] });
    // An invalid stored disc reads as not captured, never as another value.
    for (const discNumber of [0, 1000, 1.5, '1', undefined, {}]) {
        assert.equal(catalogReviewSourceDisc({ ...v1.tracks[0], discNumber }), null, String(discNumber));
        assert.equal('discNumber' in catalogReviewSourceView({ ...v1, tracks: [{ ...v1.tracks[0], discNumber }] }).tracks[0], false, String(discNumber));
    }
    assert.deepEqual([catalogReviewSourceDisc({ discNumber: 999 }), catalogReviewSourceDisc({ discNumber: null }), catalogReviewSourceDisc({}), catalogReviewSourceDisc(Object.create({ discNumber: 1 })), catalogReviewSourceDisc(null)],
        [{ value: 999 }, { value: null }, null, null, null]);
    const applied = { operationId: '00000009-0000-4000-8000-0000000000d4', at: '2026-11-01T09:00:00.000Z', fields: [{ scope: 'album', slotId: null, field: 'title' }, { scope: 'track', slotId: slot, field: 'discNumber' },
        { scope: 'album', slotId: null, field: 'title' }, { scope: 'album', slotId: null, field: 'discNumber' }, { scope: 'label', slotId: null, field: 'title' }, { scope: 'track', slotId: slot, field: 'trackNumber', extra: true },
        { scope: 'track', slotId: slot, field: 'artists' }], extra: 1 } as unknown as CatalogReviewApplied;
    assert.deepEqual(catalogReviewAppliedView(applied, new Set([slot, slotTwo])), { operationId: applied.operationId, at: applied.at,
        fields: [{ scope: 'album', slotId: null, field: 'title' }, { scope: 'track', slotId: slot, field: 'discNumber' }, { scope: 'track', slotId: slot, field: 'trackNumber' }] });
    assert.deepEqual(catalogReviewAppliedView({ ...applied, fields: 'x' } as unknown as CatalogReviewApplied), { operationId: applied.operationId, at: applied.at, fields: [] });
    assert.equal(catalogReviewAppliedView(undefined), null);
    // At most 2 + 3 per file fields are shown.
    const many = Array.from({ length: 110 }, (_, index) => ['title', 'discNumber', 'trackNumber'].map(field => ({ scope: 'track', slotId: `00000009-0000-4000-a000-${String(index).padStart(12, '0')}`, field }))).flat();
    assert.equal(catalogReviewAppliedView({ ...applied, fields: [...applied.fields, ...many] } as unknown as CatalogReviewApplied)!.fields.length, 302);
    // Views never throw on malformed stored data.
    for (const raw of [null, 'x', [], { album: null, tracks: 'x' }, { album: [], tracks: [null, 1, { slotId: 'bad' }] }]) {
        assert.doesNotThrow(() => catalogReviewSourceView(raw)); assert.deepEqual(catalogReviewSourceView(raw).tracks, [], JSON.stringify(raw));
        assert.doesNotThrow(() => catalogReviewAppliedView(raw as unknown as CatalogReviewApplied));
    }
});

test('the Draft v2 editor view keeps only readable entries, label and values, one track per slot in stored order, and never throws', () => {
    const importId = '0000000000000000000000c1', slotA = '00000009-0000-4000-a000-0000000000c1', slotB = '00000009-0000-4000-a000-0000000000c2';
    const manifest = { rootLabel: '', files: [slotA, slotB].map(slotId => ({ slotId, filename: 'Synthetic.mp3', relativePath: 'Synthetic.mp3', byteLength: null })) };
    const key = (n: number) => `00000009-0000-4000-8000-${String(n).padStart(12, '0')}`, guest = (n: number) => ({ key: key(100 + n), name: `Guest ${n}`, role: 'featured', joinPhrase: '', musicBrainzId: null });
    const stored = {
        album: { title: 'Synthetic Album', futureAlbumField: 1, label: { name: 'Synthetic Label', musicBrainzId: '00000009-0000-4000-9000-0000000000AB', futureLabelField: 1 }, releaseDate: { year: 2026, month: 3, day: null }, visibility: 'public',
            artists: [
                { key: key(1), name: 'Kept', role: 'primary', joinPhrase: ' & ', musicBrainzId: '00000009-0000-4000-9000-0000000000AA', futureEntryField: true },
                { key: key(1), name: 'Duplicate key', role: 'primary', joinPhrase: null, musicBrainzId: null }, { key: 'not-a-key', name: 'Invalid key', role: 'primary', joinPhrase: null, musicBrainzId: null },
                { key: key(2), name: '', role: 'featured', joinPhrase: null, musicBrainzId: null }, { key: key(3), name: 'x'.repeat(201), role: 'featured', joinPhrase: null, musicBrainzId: null },
                { key: key(4), name: 'Unknown role', role: 'performer', joinPhrase: null, musicBrainzId: null }, 'not an entry',
                { key: key(5), name: 'Long phrase', role: 'featured', joinPhrase: 'x'.repeat(17), musicBrainzId: 'not-an-id' },
                ...Array.from({ length: 25 }, (_, index) => guest(index))
            ] },
        tracks: [{ slotId: slotB, title: 'Second', discNumber: 2, trackNumber: 1, futureTrackField: 1 }, { slotId: slotB, title: 'Duplicate slot', discNumber: 1, trackNumber: 1 },
            { slotId: '00000009-0000-4000-a000-0000000000ff', title: 'Unknown slot', discNumber: 1, trackNumber: 1 }],
        futureTopLevel: 1
    };
    const copy = JSON.stringify(stored), view = importDraftV2View(stored, manifest, importId);
    assert.equal(JSON.stringify(stored), copy, 'the stored draft is never changed');
    // At most 20 readable entries in stored order; an unreadable phrase or ID becomes empty, never another value.
    assert.deepEqual(view.album.artists, [
        { key: key(1), name: 'Kept', role: 'primary', joinPhrase: ' & ', musicBrainzId: '00000009-0000-4000-9000-0000000000aa' },
        { key: key(5), name: 'Long phrase', role: 'featured', joinPhrase: null, musicBrainzId: null },
        ...Array.from({ length: 18 }, (_, index) => ({ ...guest(index), joinPhrase: null }))
    ]);
    assert.deepEqual({ ...view.album, artists: [] }, { title: 'Synthetic Album', artists: [], label: { name: 'Synthetic Label', musicBrainzId: '00000009-0000-4000-9000-0000000000ab' }, releaseDate: { year: 2026, month: 3, day: null }, visibility: 'public' });
    // Stored track order first, then each missing manifest slot; unknown and repeated slots are dropped.
    assert.deepEqual(view.tracks, [{ slotId: slotB, title: 'Second', discNumber: 2, trackNumber: 1 }, { slotId: slotA, title: '', discNumber: null, trackNumber: null }]);
    // Out-of-range values become empty; unknown visibility is hidden, the safer reading.
    const bounded = importDraftV2View({ album: { title: 't'.repeat(301), artists: 'x', label: { name: '' }, releaseDate: { year: 2026, month: 13, day: null }, visibility: 'unlisted' },
        tracks: [{ slotId: slotA, title: 't'.repeat(301), discNumber: 1000, trackNumber: 10000 }, { slotId: slotB, title: 'Kept', discNumber: 1.5, trackNumber: 0 }] }, manifest, importId);
    assert.deepEqual(bounded, { album: { title: '', artists: [], label: null, releaseDate: null, visibility: 'hidden' },
        tracks: [{ slotId: slotA, title: '', discNumber: null, trackNumber: null }, { slotId: slotB, title: 'Kept', discNumber: null, trackNumber: null }] });
    for (const raw of [null, 'x', [], { album: null, tracks: null }, { album: [], tracks: [null, 1] }]) assert.deepEqual(importDraftV2View(raw, manifest, importId).tracks.map(track => track.slotId), [slotA, slotB], JSON.stringify(raw));
    // A v1 draft is the converted view, keyed by the project.
    const v1 = { album: { title: 'Synthetic Album', artistName: ' Lorem ', releaseDate: null, visibility: 'hidden' }, tracks: [{ slotId: slotA, title: 'One', trackNumber: 1 }] };
    assert.deepEqual(importDraftV2View(v1, manifest, importId), { album: { title: 'Synthetic Album', artists: [{ key: legacyArtistEntryKey(importId), name: 'Lorem', role: 'primary', joinPhrase: null, musicBrainzId: null }], label: null, releaseDate: null, visibility: 'hidden' },
        tracks: [{ slotId: slotA, title: 'One', discNumber: null, trackNumber: 1 }, { slotId: slotB, title: '', discNumber: null, trackNumber: null }] });
});

test('the Draft v2 suggestion view maps legacy Artist names, keeps readable album Artist suggestions whole and drops any other', () => {
    const importId = '0000000000000000000000c2', slot = '00000009-0000-4000-a000-0000000000c3', slots = new Set([slot]), generation = 2;
    const lorem = { key: '00000009-0000-4000-8000-0000000000c1', name: 'Lorem', role: 'primary', joinPhrase: null, musicBrainzId: null };
    const artists = { scope: 'album', slotId: null, field: 'artists', baseline: [], value: [lorem], source: 'folder', evidence: 'Synthetic Folder', id: 'a'.repeat(24), generation, decision: 'pending' };
    const legacy = { ...artists, id: 'b'.repeat(24), field: 'artistName', baseline: '', value: ' Ipsum ' }, title = { ...artists, id: 'c'.repeat(24), field: 'title', baseline: '', value: 'Album' };
    const view = (raw: unknown[]) => importSuggestionsV2View(raw, generation, slots, importId);
    const dropped = [
        { ...artists, id: '1'.repeat(24), value: [{ ...lorem, name: '' }] }, { ...artists, id: '2'.repeat(24), value: [{ ...lorem, role: 'performer' }] },
        { ...artists, id: '3'.repeat(24), baseline: 'Lorem' }, { ...artists, id: '4'.repeat(24), value: Array.from({ length: 21 }, (_, index) => ({ ...lorem, key: `00000009-0000-4000-8000-${String(index).padStart(12, '0')}`, name: `N${index}` })) },
        { ...artists, id: '5'.repeat(24), scope: 'track', slotId: slot }, { ...artists, id: '6'.repeat(24), generation: 1 }, { ...artists, id: '7'.repeat(24), source: 'lookup-musicbrainz' },
        { ...artists, id: '8'.repeat(24), value: [lorem, { ...lorem, name: 'Same key' }] }, { ...title, id: '9'.repeat(24), field: 'label' }, null, 'x'
    ];
    assert.deepEqual(view([artists, ...dropped, legacy, title]).map(suggestion => suggestion.id), [artists.id, legacy.id, title.id]);
    // Unknown entry fields are dropped, never echoed.
    assert.deepEqual(view([{ ...artists, value: [{ ...lorem, futureEntryField: true }] }]), [artists]);
    assert.deepEqual(view([legacy]), [{ ...legacy, field: 'artists', baseline: [], value: [{ key: legacyArtistEntryKey(importId), name: 'Ipsum', role: 'primary', joinPhrase: null, musicBrainzId: null }] }]);
    assert.equal(view(Array.from({ length: 1001 }, (_, index) => ({ ...title, id: String(index).padStart(24, '0') }))).length, 1000);
});

